export type TranslationKey = keyof typeof messages
export type TranslationValues = Record<string, string | number>

export function translate(locale: string, key: TranslationKey, values: TranslationValues = {}): string {
  const language = locale.split('-')[0] as Language
  const languageIndex = SUPPORTED_LANGUAGES.indexOf(language)
  const template = messages[key][languageIndex < 0 ? 0 : languageIndex] ?? messages[key][0]
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`))
}
